using Microsoft.EntityFrameworkCore;

// EF Core 9 Cosmos DB breaking changes applied below.

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1: Cosmos discriminator renamed from "Discriminator" to "$type".
        // Existing documents already store "Discriminator", so we must opt back in
        // to preserve compatibility with pre-EF-Core-9 data.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");
    }

    // BREAKING CHANGE 2: Synchronous Cosmos DB queries now throw
    // InvalidOperationException. All queries must use async equivalents.
    //
    //   BEFORE (EF Core 8 – no longer works):
    //     var items = db.Products.ToList();
    //     var first = db.Products.First();
    //
    //   AFTER (EF Core 9):
    //     var items = await db.Products.ToListAsync();
    //     var first = await db.Products.FirstAsync();
    //
    // If you absolutely cannot use async, set the following as a temporary
    // workaround (not recommended):
    //   AppContext.SetSwitch("Microsoft.EntityFrameworkCore.Issue27289", true);
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

